function choose(i){if(!s||s.chosen||s.done||!Number.isInteger(i)||i<0||i>2)return;const ev=currentEvent(),o=ev.options[i];if(!o)return;for(const[k,v]of Object.entries(o[2]))s[k]=k==='money'?Math.max(-50,s[k]+v):k==='appeal'?clamp(s[k]+v,-15,25):clamp(s[k]+v);s.chosen=true;s.chosenIndex=i;s.eventId=ev.id;s.last=o[3];s.history.push({year:s.year,title:o[0],eventId:ev.id,optionIndex:i});render();animate(o[3]);if(!persist())notify('저장 공간이 부족합니다. 현재 플레이는 계속할 수 있습니다.')}
function advance(){if(!s||!s.chosen||s.done)return;const followingEventId=nextEventId(s,s.year+1);if(s.eventCatalogVersion!==catalogVersion)s.eventScheduleMode='remaining';s.eventCatalogVersion=catalogVersion;const school=schoolMap.get(s.schoolId),old=PopulationModel.total(s.grades,s.special),previous=PopulationModel.forecast(school,s.year),next=PopulationModel.forecast(school,s.year+1),effects=PopulationModel.effects(s);s.grades=PopulationModel.transition(s.grades,previous,next,effects);s.special=next.special;s.year++;const total=PopulationModel.total(s.grades,s.special);s.money=clamp(s.money+Math.round(16+total/Math.max(1,s.base)*6)-Math.round(s.facilities*.035),-50,250);s.teacher=clamp(s.teacher-2);s.facilities=clamp(s.facilities-2);s.appeal=clamp(s.appeal-1,-15,25);s.points.push({year:s.year,total});const gap=total-next.total;s.last=`${s.year}년, ${total.toLocaleString('ko-KR')}명이 새 학년을 시작합니다. ${old>total?`지난해보다 ${old-total}명 감소.`:old<total?`지난해보다 ${total-old}명 증가.`:'지난해 학생 수 유지.'} 인구 기준선 ${next.total.toLocaleString('ko-KR')}명 대비 ${gap>=0?'+':''}${gap}명입니다.`;s.chosen=false;s.chosenIndex=null;s.done=s.year>=2045;if(!s.done)s.eventId=followingEventId;render();animate(s.done?'🎓 교장 인생의 결말':'🎓 새로운 학년!');persist()}
function updateForecast(school,total){const base=PopulationModel.forecast(school,s.year),gap=total-base.total;const fx=PopulationModel.effects(s);$('comparison').innerHTML=`<span>인구 기준선<b>${base.total.toLocaleString('ko-KR')}명</b></span><span>내 선택의 차이<b class="${gap>=0?'positive':'negative'}">${gap>=0?'+':''}${gap.toLocaleString('ko-KR')}명</b></span>`;$('chartNote').textContent=`${s.year}년 기준 · 기준선은 자체 추계, 녹색 선은 게임 결과입니다. 현재 정책의 신입생 유입 효과 ${(fx.admission*100)>=0?'+':''}${(fx.admission*100).toFixed(1)}% (게임 가정).`;const played=new Map(s.points.map(p=>[p.year,p.total]));$('forecastTable').innerHTML='<table><thead><tr><th>연도</th><th>인구 기준선</th><th>내 학교</th><th>차이</th></tr></thead><tbody>'+school.forecast.map(p=>{const v=played.get(p.year),diff=v===undefined?null:v-p.total;return `<tr class="${p.year===s.year?'current':''}"><th>${p.year}${p.year===2026?' 공시':''}</th><td>${p.total.toLocaleString('ko-KR')}명</td><td>${v===undefined?'—':v.toLocaleString('ko-KR')+'명'}</td><td>${diff===null?'—':(diff>=0?'+':'')+diff+'명'}</td></tr>`}).join('')+'</tbody></table><p>2026년은 공시 값, 2027~2045년은 자체 추계. 미래의 내 학교 값은 게임을 진행하면 표시됩니다.</p>'}
function draw(){if(!s||$('game').hidden)return;const school=schoolMap.get(s.schoolId),c=$('chart'),r=c.getBoundingClientRect(),w=Math.max(200,r.width),h=r.height||155,d=Math.min(window.devicePixelRatio||1,3);c.width=w*d;c.height=h*d;const ctx=c.getContext('2d');if(!ctx)return;ctx.scale(d,d);ctx.clearRect(0,0,w,h);const arr=s.points,base=school.forecast,max=Math.max(1,...base.map(x=>x.total),...arr.map(x=>x.total))*1.12,left=39,right=w-14,top=14,bottom=h-24;ctx.strokeStyle='#e7eddf';ctx.fillStyle='#9caa8f';ctx.font='9px system-ui';for(let i=0;i<4;i++){const v=max*(1-i/3),y=top+(bottom-top)*i/3;ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(right,y);ctx.stroke();ctx.fillText(Math.round(v).toLocaleString('ko-KR'),1,y+3)}const xx=y=>left+(y-2026)/19*(right-left),yy=v=>bottom-v/max*(bottom-top);ctx.strokeStyle='#a6aea0';ctx.lineWidth=1.7;ctx.setLineDash([4,4]);ctx.beginPath();base.forEach((p,i)=>i?ctx.lineTo(xx(p.year),yy(p.total)):ctx.moveTo(xx(p.year),yy(p.total)));ctx.stroke();ctx.setLineDash([]);ctx.beginPath();arr.forEach((p,i)=>i?ctx.lineTo(xx(p.year),yy(p.total)):ctx.moveTo(xx(p.year),yy(p.total)));ctx.lineTo(xx(arr.at(-1).year),bottom);ctx.lineTo(left,bottom);ctx.closePath();const gradient=ctx.createLinearGradient(0,top,0,bottom);gradient.addColorStop(0,'#79a66940');gradient.addColorStop(1,'#79a66900');ctx.fillStyle=gradient;ctx.fill();ctx.strokeStyle='#38764e';ctx.lineWidth=2.4;ctx.beginPath();arr.forEach((p,i)=>i?ctx.lineTo(xx(p.year),yy(p.total)):ctx.moveTo(xx(p.year),yy(p.total)));ctx.stroke();ctx.fillStyle='#96a387';[2026,2030,2035,2040,2045].forEach(y=>ctx.fillText(y,xx(y)-11,h-6));const last=arr.at(-1);ctx.fillStyle='#dcb65e';ctx.beginPath();ctx.arc(xx(last.year),yy(last.total),4,0,Math.PI*2);ctx.fill();c.setAttribute('aria-label',`회색 인구 기준선: ${base.map(p=>p.year+'년 약 '+p.total+'명').join(', ')}. 내 선택의 결과: ${arr.map(p=>p.year+'년 '+p.total+'명').join(', ')}`)}
function reset(){if(!s||!confirm(`${schoolMap.get(s.schoolId).name}의 인구 반영판 진행을 지우고 2026년 공시 값에서 다시 시작할까요?`))return;s=initial(schoolMap.get(s.schoolId));persist();render();notify('2026년 실제 공시 학생 수에서 다시 시작했습니다.')}
$('region').innerHTML+=[...new Set(SCHOOLS.map(x=>x.region))].sort((a,b)=>a.localeCompare(b,'ko')).map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');$('schoolCount').textContent=SCHOOLS.length;$('region').onchange=listSchools;$('search').oninput=listSchools;$('schoolList').onclick=e=>{const b=e.target.closest('[data-school]');if(b)selectSchool(b.dataset.school)};$('choices').onclick=e=>{const b=e.target.closest('[data-choice]');if(b)choose(Number(b.dataset.choice))};$('start').onclick=enterGame;$('cancelSetup').onclick=()=>{if(s){$('setup').hidden=true;$('game').hidden=false;render();window.scrollTo({top:0,behavior:'instant'})}};$('switchSchool').onclick=showSetup;$('next').onclick=advance;$('restart').onclick=reset;$('save').onclick=()=>notify(persist()?'현재 기기에 진행 상황을 저장했습니다.':'진행 상황을 저장하지 못했습니다. 브라우저 저장 공간을 확인해 주세요.');addEventListener('resize',draw);addEventListener('pagehide',()=>{if(s)persist()});
